import React, { createContext, useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';

interface Beer {
  Name: string;
  Price: string | number;
  Type: string;
  ABV: string;
  Description: string;
  image?: string;
  quantity?: number;
}

interface Order {
  beers: Beer[];
  total: number;
}

interface OrderContextType {
  order: Order;
  addToOrder: (beer: Beer) => void;
  removeFromOrder: (beerName: string) => void;
  updateQuantity: (beerName: string, quantity: number) => void;
  checkout: () => void;
  clearOrder: () => void;
}

const OrderContext = createContext<OrderContextType>({
  order: { beers: [], total: 0 },
  addToOrder: () => {},
  removeFromOrder: () => {},
  updateQuantity: () => {},
  checkout: () => {},
  clearOrder: () => {},
});

export const useOrder = () => useContext(OrderContext);

export const OrderProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [order, setOrder] = useState<Order>({ beers: [], total: 0 });
  const navigate = useNavigate();

  const addToOrder = (beer: Beer) => {
    setOrder(prev => {
      // 确保Price是数字
      const beerPrice = typeof beer.Price === 'string' ? parseFloat(beer.Price) : beer.Price;
      const beerWithPrice = {...beer, Price: beerPrice.toString(), quantity: 1};
      
      // 检查是否已经有相同的啤酒
      const existingBeerIndex = prev.beers.findIndex(b => b.Name === beer.Name);
      
      let newBeers;
      if (existingBeerIndex >= 0) {
        // 如果已经存在，增加数量
        newBeers = [...prev.beers];
        newBeers[existingBeerIndex] = {
          ...newBeers[existingBeerIndex],
          quantity: (newBeers[existingBeerIndex].quantity || 1) + 1
        };
      } else {
        // 如果不存在，添加新的
        newBeers = [...prev.beers, beerWithPrice];
      }
      
      // 计算新的总价
      const newTotal = newBeers.reduce((sum, b) => {
        const price = typeof b.Price === 'string' ? parseFloat(b.Price) : b.Price;
        const quantity = b.quantity || 1;
        return sum + (price * quantity);
      }, 0);
      
      return {
        beers: newBeers,
        total: newTotal,
      };
    });
  };

  const removeFromOrder = (beerName: string) => {
    setOrder(prev => {
      const existingBeerIndex = prev.beers.findIndex(beer => beer.Name === beerName);
      
      if (existingBeerIndex >= 0 && prev.beers[existingBeerIndex].quantity && prev.beers[existingBeerIndex].quantity! > 1) {
        // 如果数量大于1，减少数量
        const newBeers = [...prev.beers];
        newBeers[existingBeerIndex] = {
          ...newBeers[existingBeerIndex],
          quantity: newBeers[existingBeerIndex].quantity! - 1
        };
        
        // 计算新的总价
        const newTotal = newBeers.reduce((sum, b) => {
          const price = typeof b.Price === 'string' ? parseFloat(b.Price) : b.Price;
          const quantity = b.quantity || 1;
          return sum + (price * quantity);
        }, 0);
        
        return {
          beers: newBeers,
          total: newTotal,
        };
      } else {
        // 如果数量为1或未定义，移除该啤酒
        const newBeers = prev.beers.filter(beer => beer.Name !== beerName);
        const newTotal = newBeers.reduce((sum, b) => {
          const price = typeof b.Price === 'string' ? parseFloat(b.Price) : b.Price;
          const quantity = b.quantity || 1;
          return sum + (price * quantity);
        }, 0);
        
        return {
          beers: newBeers,
          total: newTotal,
        };
      }
    });
  };

  const clearOrder = () => {
    setOrder({ beers: [], total: 0 });
  };

  const checkout = () => {
    if (order.beers.length === 0) {
      alert('Please add beers to your order first!');
      return;
    }
    // 跳转到订单成功页面
    navigate('/order-success');
  };

  const updateQuantity = (beerName: string, quantity: number) => {
    if (quantity <= 0) {
      // 如果数量小于等于0，移除该啤酒
      removeFromOrder(beerName);
      return;
    }
    
    setOrder(prev => {
      const existingBeerIndex = prev.beers.findIndex(beer => beer.Name === beerName);
      
      if (existingBeerIndex >= 0) {
        // 更新数量
        const newBeers = [...prev.beers];
        newBeers[existingBeerIndex] = {
          ...newBeers[existingBeerIndex],
          quantity: quantity
        };
        
        // 计算新的总价
        const newTotal = newBeers.reduce((sum, b) => {
          const price = typeof b.Price === 'string' ? parseFloat(b.Price) : b.Price;
          const quantity = b.quantity || 1;
          return sum + (price * quantity);
        }, 0);
        
        return {
          beers: newBeers,
          total: newTotal,
        };
      }
      
      return prev;
    });
  };

  return (
    <OrderContext.Provider value={{ order, addToOrder, removeFromOrder, updateQuantity, checkout, clearOrder }}>
      {children}
    </OrderContext.Provider>
  );
};

export default OrderContext;